{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시장에게 흡연의 해로움을 알리는 일이 의무인지, 시장이 할 수 있다고 정한 일인지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "흡연의 해로움을 알리는 일은 시장이 하여야 하는 의무이다. 서울특별시 금연환경 조성 및 간접흡연 피해방지조례 제4조 제2항은 시장이 금연환경조성을 위해 흡연이 건강에 해롭다는 것을 교육·홍보하여야 한다고 정하고 있다.",
          "b_ids": "금연:제4조제2항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "서울시장에게 금연지도원을 위촉해 운영하는 일이 의무인지, 시장이 할 수 있다고 정한 일인지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "금연지도원을 위촉하여 운영하는 일은 시장이 할 수 있다고 정한 일이다. 서울특별시 금연환경 조성 및 간접흡연 피해방지조례 제9조의2 제1항은 시장이 법 제9조의5에 따라 금연지도원을 위촉하여 운영할 수 있다고 정하고 있다.",
          "b_ids": "금연:제9조의2제1항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
